<?php $title = __('Vehicles'); ?>
<div class="toolbar"><span class="muted"><?= __('Vehicle-wise expenses feed the vehicle-wise and date-wise reports.') ?></span><span style="flex:1"></span><?php if (Auth::can('vehicles.manage')): ?><a class="btn btn-primary" href="<?= e(url('vehicles/new')) ?>"><?= __('+ New Vehicle') ?></a><?php endif; ?></div>
<div class="panel print-area"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Reg. No') ?></th><th><?= __('Name / Type') ?></th><th><?= __('Make / Model') ?></th><th><?= __('Driver') ?></th><th class="num"><?= __('Fuel (L)') ?></th><th class="num"><?= __('Fuel Cost') ?></th><th class="num"><?= __('Expenses') ?></th><th class="num"><?= __('Total Cost') ?></th><th><?= __('Status') ?></th><th></th></tr></thead>
<tbody><?php foreach ($rows as $v): ?><tr><td class="mono"><?= e($v['reg_no']) ?></td><td><?= e($v['name'] ?: '—') ?><?php if (!empty($v['vehicle_type'])): ?><br><span class="muted" style="font-size:11px"><?= e($v['vehicle_type']) ?></span><?php endif; ?></td><td><?= e(trim(($v['make'] ?? '') . ' ' . ($v['model'] ?? '') . ($v['year'] ? ' (' . $v['year'] . ')' : '')) ?: '—') ?></td><td><?= e($v['driver_name'] ?? '—') ?></td>
<td class="num"><?= qty($v['fuel_liters']) ?></td><td class="num"><?= money($v['fuel_total'], false) ?></td><td class="num"><?= money($v['maint_total'], false) ?></td><td class="num"><?= money($v['fuel_total'] + $v['maint_total'], false) ?></td>
<td><span class="badge <?= ($v['status'] ?? 'active') === 'active' ? 'green' : (($v['status'] ?? '') === 'retired' ? 'red' : 'gray') ?>"><?= e(strtoupper($v['status'] ?? 'active')) ?></span></td>
<td><a class="btn btn-outline btn-sm" href="<?= e(url('vehicles/' . (int)$v['id'])) ?>"><?= __('Details') ?></a></td></tr>
<?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="10" class="muted"><?= __('No vehicles on file.') ?></td></tr><?php endif; ?></tbody></table></div></div>
